const mails = await api.get('/mails', { label: 'complaint' });
const complaintCustomerIds = new Set();
for (const m of mails.items) {
  if (m.customer_id) complaintCustomerIds.add(m.customer_id);
}
// fetch customers with delayed orders
const customers = await api.get('/customers');
const result = [];
for (const c of customers.items) {
  if (c.order && c.order.status === 'delayed' && complaintCustomerIds.has(c.id)) {
    result.push(c.id);
  }
}
return result;
